create table if not exists public.public_market_catalog(market_id uuid primary key,code text not null unique,display_name text not null,default_language_code text not null,default_currency_code text not null);
create table if not exists public.public_location_catalog(location_id uuid primary key,market_id uuid not null,parent_id uuid,location_type text not null,display_name text not null,canonical_code text);
create table if not exists public.public_service_catalog(service_entity_id uuid primary key,canonical_key text not null unique,display_name text not null,risk_level smallint not null default 0);
alter table public.public_market_catalog enable row level security; alter table public.public_location_catalog enable row level security; alter table public.public_service_catalog enable row level security;
create policy public_market_catalog_read on public.public_market_catalog for select to anon,authenticated using(true);
create policy public_location_catalog_read on public.public_location_catalog for select to anon,authenticated using(true);
create policy public_service_catalog_read on public.public_service_catalog for select to anon,authenticated using(true);
revoke all on public.public_market_catalog,public.public_location_catalog,public.public_service_catalog from anon,authenticated; grant select on public.public_market_catalog,public.public_location_catalog,public.public_service_catalog to anon,authenticated;
insert into public.public_market_catalog(market_id,code,display_name,default_language_code,default_currency_code) select id,code,case when code='NG' then 'Nigeria' else code end,default_language_code,default_currency_code from public.markets where is_active on conflict(market_id) do update set code=excluded.code,display_name=excluded.display_name,default_language_code=excluded.default_language_code,default_currency_code=excluded.default_currency_code;
insert into public.public_location_catalog(location_id,market_id,parent_id,location_type,display_name,canonical_code) select l.id,l.market_id,l.parent_id,l.location_type,coalesce(l.canonical_code,l.location_type),l.canonical_code from public.locations l where l.is_active on conflict(location_id) do update set market_id=excluded.market_id,parent_id=excluded.parent_id,location_type=excluded.location_type,display_name=excluded.display_name,canonical_code=excluded.canonical_code;
insert into public.public_service_catalog(service_entity_id,canonical_key,display_name,risk_level) select t.id,t.canonical_key,coalesce((select n.display_name from public.entity_names n where n.entity_id=t.id and n.is_primary order by n.created_at limit 1),t.canonical_key),t.risk_level from public.taxonomy_entities t where t.kind='service' and t.is_active on conflict(service_entity_id) do update set canonical_key=excluded.canonical_key,display_name=excluded.display_name,risk_level=excluded.risk_level;
